SELECT 'TI_ImportRun_session_branchId' AS relationship, COUNT(*) AS inconsistent_count FROM "ImportRun" c JOIN (SELECT id,"branchId" FROM "ImportRun") own ON own.id=c."id" WHERE c."importSessionId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT id,"branchId" FROM "ImportSession") p WHERE p.id=c."importSessionId" AND p."branchId"=own."branchId");
SELECT 'TI_ImportRun_plan_branchId' AS relationship, COUNT(*) AS inconsistent_count FROM "ImportRun" c JOIN (SELECT id,"branchId" FROM "ImportRun") own ON own.id=c."id" WHERE c."importPlanId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT p.id,s."branchId" FROM "ImportPlan" p JOIN "ImportSession" s ON s.id=p."importSessionId") p WHERE p.id=c."importPlanId" AND p."branchId"=own."branchId");
SELECT 'TI_ImportRunItem_row_branchId' AS relationship, COUNT(*) AS inconsistent_count FROM "ImportRunItem" c JOIN (SELECT i.id,r."branchId" FROM "ImportRunItem" i JOIN "ImportRun" r ON r.id=i."importRunId") own ON own.id=c."id" WHERE c."importRowId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT r.id,s."branchId" FROM "ImportRow" r JOIN "ImportSession" s ON s.id=r."importSessionId") p WHERE p.id=c."importRowId" AND p."branchId"=own."branchId");
SELECT 'TI_ImportRunItem_evaluation_branchId' AS relationship, COUNT(*) AS inconsistent_count FROM "ImportRunItem" c JOIN (SELECT i.id,r."branchId" FROM "ImportRunItem" i JOIN "ImportRun" r ON r.id=i."importRunId") own ON own.id=c."id" WHERE c."evaluationId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT e.id,s."branchId" FROM "ImportRowEvaluation" e JOIN "ImportRow" r ON r.id=e."importRowId" JOIN "ImportSession" s ON s.id=r."importSessionId") p WHERE p.id=c."evaluationId" AND p."branchId"=own."branchId");
SELECT 'TI_WhatsAppMessagePayment_payment_branchId' AS relationship, COUNT(*) AS inconsistent_count FROM "WhatsAppMessagePayment" c JOIN (SELECT m.id,m."branchId" FROM "WhatsAppMessage" m) own ON own.id=c."messageId" WHERE c."paymentId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT id,"branchId" FROM "Payment") p WHERE p.id=c."paymentId" AND p."branchId"=own."branchId");
SELECT 'ImportQuestion_row_session' AS relationship, COUNT(*) AS inconsistent_count FROM "ImportQuestion" q WHERE q."rowId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "ImportRow" r WHERE r.id=q."rowId" AND r."importSessionId"=q."importSessionId");